-- El borrador se arma solo con el texto enmascarado que ya está en la base.
SELECT reclamo_id, cliente_id, texto_enmascarado, categoria, area_derivada, respuesta_estado
FROM negocio.reclamos WHERE reclamo_id = $1;

parameters.jsCode:
// Toma el borrador: de la IA o, solo en pruebas, uno simulado para comprobar que el control lo frena.
let borrador = '', fuente;
if ($('CA85c_Redactar_IA').isExecuted) {
  fuente = 'ia';
  try { borrador = JSON.parse($('CA85c_Redactar_IA').first().json.response || '{}').respuesta || ''; } catch (e) { borrador = ''; }
} else { fuente = 'simulado (prueba)'; borrador = $('CA85c_Disparador').first().json.borrador_simulado; }
return [{ json: { borrador, fuente } }];

// El borrador solo pasa si no tiene datos personales, no promete nada y no inventa marcadores.
// El saludo y el cierre los pone el código, no la IA.
const r = $('CA85c_Leer_reclamo').first().json;
let b = String($input.first().json.borrador || '').trim();
b = b.replace(/^(estimad[oa](\/a)?|hola|buen(os|as)\s+\w+)[^,\n]*,\s*/i, '');   // si la IA igual saludó, se quita
b = b.charAt(0).toUpperCase() + b.slice(1);
const motivos = [];
if (!b) motivos.push('La IA no devolvió un borrador');
const marcasReclamo = new Set(String(r.texto_enmascarado || '').match(/\[[A-Z]+_\d+\]/g) || []);
const ajenas = (b.match(/\[[A-Z]+_\d+\]/g) || []).filter((m) => !marcasReclamo.has(m));
if (ajenas.length) motivos.push('Usa marcadores que no están en el reclamo: ' + [...new Set(ajenas)].join(', '));
if (/[\w.+-]+@[\w-]+\.[\w.-]+|\b\d{7,8}\b|\b\d{2,4}[-\s]\d{4}[-\s]\d{4}\b|\b\d{22}\b|\b\d{2}-\d{8}-\d\b/.test(b)) motivos.push('Contiene un dato personal');
const PROMESAS = [
  [/reintegr|reembols|devoluci[oó]n del (dinero|importe|pago)/i, 'reintegro'],
  [/compensaci|bonificaci|descuento|gratis|sin cargo|sin costo/i, 'compensación o descuento'],
  [/garantiz|le aseguramos|te aseguramos|nos comprometemos a (entregar|enviar|pagar|devolver)/i, 'garantía'],
  [/\b(hoy|mañana|manana|esta semana|el lunes|el martes|el miércoles|el jueves|el viernes)\b|\b\d{1,2}\/\d{1,2}\b|\ben \d+\s*(hs|horas|días|dias)\b|\b\d+\s*(hs|horas)\b/i, 'fecha o plazo'],
  [/\$\s*\d|\bpesos\b|\d+[.,]\d{3}/i, 'monto'],
];
for (const [re, que] of PROMESAS) if (re.test(b)) motivos.push('Promete algo que no puede prometer (' + que + ')');
if (b.length > 700) motivos.push('Demasiado largo (' + b.length + ' caracteres)');
let final = b;
if (motivos.length === 0) {
  const saludo = marcasReclamo.has('[NOMBRE_1]') ? 'Estimado/a [NOMBRE_1],' : 'Estimado/a,';
  final = saludo + '\n\n' + b + '\n\nPor su seguridad, no envíe datos personales (DNI, teléfono, dirección o datos bancarios) por este medio.';
  if (!r.cliente_id) final += ' Para avanzar con su reclamo, complete sus datos en este formulario seguro: [LINK_FORMULARIO]';
}
return [{ json: { valido: motivos.length === 0, borrador: final, motivos, fuente: $input.first().json.fuente, cliente_identificado: !!r.cliente_id } }];

const r = $('CA85c_Leer_reclamo').first().json;
return [{ json: { modo: 'pedir', automatizacion_id: 'A10', objeto: r.reclamo_id, accion: 'enviar_respuesta_cliente',
  motivo: `Borrador de primera respuesta (${r.categoria}, área ${r.area_derivada}) para revisar antes de enviar` } }];

