-- El borrador no pasó el control: no se guarda y el agente redacta a mano.
INSERT INTO control.cola_revision (origen, automatizacion_id, documento_id, motivo, prioridad, asignado_a)
VALUES ('reclamos', 'A10', $1, $2, 'media', 'Agente de atención');

