let estado, motivos = [], borrador = null, fuente = null, ap = {}, intentos = 0;
if (!$('CA85c_Validar_borrador').isExecuted) {
  estado = 'No corresponde';
  motivos = [!l.reclamo_id ? 'El reclamo no existe' : (!l.area_derivada ? 'El reclamo no está derivado' : 'Ya tiene un borrador (' + l.respuesta_estado + ')')];
