  const v = $('CA85c_Validar_reintento').isExecuted ? $('CA85c_Validar_reintento').first().json : $('CA85c_Validar_borrador').first().json;
  intentos = $('CA85c_Validar_reintento').isExecuted ? 2 : 1;
  fuente = v.fuente; borrador = v.borrador;
  if (!v.valido) { estado = 'Borrador descartado'; motivos = v.motivos; }
  else if ($('CA85c_Pedir_aprobacion').isExecuted) { estado = 'pendiente_aprobacion'; ap = $('CA85c_Pedir_aprobacion').first().json; }
  else { estado = 'No guardado (ya tenía borrador)'; }
}
