  : `${r.cambios.length} respuestas decididas, ${r.pendientes.length} esperando al agente`;
return [{ json: { modo: 'fin', automatizacion_id: 'A10', documento_id: doc,
  estado: r.estado === 'Borrador descartado' ? 'derivado_a_cola' : 'ok', intervencion_humana: false, modelo_ia: r.modelo_ia || '',
  auditar: false, actor: 'A10', accion: 'borrador de respuesta', motivo, respuesta: r } }];

